import { HugeiconsIcon } from "@hugeicons/react";
import PencilIcon from "@hugeicons/core-free-icons/PencilIcon";
import Share01Icon from "@hugeicons/core-free-icons/Share01Icon";
import TrashIcon from "@hugeicons/core-free-icons/TrashIcon";

import { Button } from "@/registry/erbium/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuList,
} from "@/registry/erbium/ui/dropdown-menu";

export function DropdownMenuError() {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" />}>Actions</DropdownMenuTrigger>
      <DropdownMenuContent>
        <DropdownMenuList>
          <DropdownMenuGroup>
            <DropdownMenuItem>
              <HugeiconsIcon icon={PencilIcon} />
              Edit
            </DropdownMenuItem>
            <DropdownMenuItem>
              <HugeiconsIcon icon={Share01Icon} />
              Share
            </DropdownMenuItem>
          </DropdownMenuGroup>
          <DropdownMenuSeparator />
          <DropdownMenuGroup>
            <DropdownMenuItem variant="error">
              <HugeiconsIcon icon={TrashIcon} />
              Delete
            </DropdownMenuItem>
          </DropdownMenuGroup>
        </DropdownMenuList>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { DropdownMenuError } from "../examples/dropdown-menu-error";

const Example = () => <DropdownMenuError />;

export default Example;
